import * as THREE from 'three';import {GLTFLoader} from 'three/addons/loaders/GLTFLoader.js';
let templatePromise;
export const PIANO_PLACEMENT=Object.freeze({x:-2.65,y:.033,z:-1.20,seatY:.811,seatZ:-.16});
export function createPianoView(template){const root=template.clone(true),keys=new Map(),base=new Map(),geometry=new Map(),material=new Map();let alive=true;root.name='music.landmark';root.position.set(PIANO_PLACEMENT.x,PIANO_PLACEMENT.y,PIANO_PLACEMENT.z);root.traverse(o=>{if(o.isMesh){if(!geometry.has(o.geometry))geometry.set(o.geometry,o.geometry.clone());o.geometry=geometry.get(o.geometry);const clone=m=>{if(!material.has(m))material.set(m,m.clone());return material.get(m);};o.material=Array.isArray(o.material)?o.material.map(clone):clone(o.material);o.castShadow=o.receiveShadow=true;}if(o.userData.role==='pianoKey'){keys.set(o.userData.midi,o);base.set(o.userData.midi,o.rotation.x);}});return{root,keys,setPressed(midi,on){if(alive&&keys.has(midi))keys.get(midi).rotation.x=base.get(midi)+(on?.035:0);},resetKeys(){for(const[m,k]of keys)k.rotation.x=base.get(m);},dispose(){if(!alive)return;alive=false;for(const g of geometry.values())g.dispose();for(const m of material.values())m.dispose();root.removeFromParent();root.clear();}};}
export async function attachMusicAsset(view,{loader=null}={}){const music=view.getZoneView?.('music')??(view.roomId==='music'?view:null);if(!music?.schoolView?.installPiano)return view;try{templatePromise??=(loader?loader():new GLTFLoader().loadAsync(new URL('../music/grand-piano.glb',import.meta.url).href).then(g=>g.scene)).catch(e=>{templatePromise=null;throw e;});const template=await templatePromise;if(!music.schoolView.disposed)music.schoolView.installPiano(template);return view;}catch(e){view.dispose();throw e;}}
